patch_result.patch:
--- a/ffmpeg/libavformat/mov.c
+++ b/ffmpeg/libavformat/mov.c
@@ -1113,6 +1113,9 @@
     int blocks = 0;
     unsigned char iv[16];

+    if (!c->aes_decrypt)
+        return AVERROR_INVALIDDATA;
+
     memcpy(iv, c->file_iv, 16); // iv is overwritten
     blocks = size >> 4; // trailing bytes are not encrypted!
     av_aes_init(c->aes_decrypt, c->file_key, 128, 1);

args:
@@ -1110,10 +1110,14 @@
 static int aax_filter(uint8_t *input, int size, MOVContext *c)
 {
     int blocks = 0;
     unsigned char iv[16];
+
+    if (!c->aes_decrypt)
+        return AVERROR_INVALIDDATA;

     memcpy(iv, c->file_iv, 16); // iv is overwritten
     blocks = size >> 4; // trailing bytes are not encrypted!
     av_aes_init(c->aes_decrypt, c->file_key, 128, 1);
     av_aes_crypt(c->aes_decrypt, input, input, blocks, iv, 1);
